import{i as e,r as t,s as n,t as r}from"./app-B2eeld61.js";var i=JSON.parse(`{"path":"/guide/json/","title":"JSON и сериализация","lang":"ru-RU","frontmatter":{"prev":"/guide/file-io/practice.md","next":"/guide/json/tests.md"},"git":{"updatedTime":1792180577000,"contributors":[{"name":"Danil Chugaev","username":"","email":"danilchugaev@mail.ru","commits":1}],"changelog":[{"hash":"bf0f364e47155728a8fd510854ec852915499af5","time":1792180577000,"email":"danilchugaev@mail.ru","author":"Danil Chugaev","message":"fix"}]},"filePathRelative":"guide/json/README.md"}`),a={name:`README.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="json-и-сериализация" tabindex="-1"><a class="header-anchor" href="#json-и-сериализация"><span>JSON и сериализация</span></a></h1><h2 id="цель-урока" tabindex="-1"><a class="header-anchor" href="#цель-урока"><span>Цель урока</span></a></h2><p>Научиться преобразовывать структуры Go в JSON и обратно, управлять именами полей через теги, вынести JSON-хранилище в отдельный пакет и проверить его во временной директории.</p><p>Текстовый экспорт из прошлой главы удобен для чтения человеком, но программа не может надёжно восстановить из него структуры <code>Task</code>. JSON хранит данные в стандартном структурированном формате, понятном Go, HTTP API и многим другим системам.</p><h2 id="что-такое-json" tabindex="-1"><a class="header-anchor" href="#что-такое-json"><span>Что такое JSON</span></a></h2><p>JSON (JavaScript Object Notation) — текстовый формат обмена данными. Объекты записывают в фигурных скобках, массивы — в квадратных:</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;id&quot;</span><span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;title&quot;</span><span class="token operator">:</span> <span class="token string">&quot;Купить молоко&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;priority&quot;</span><span class="token operator">:</span> <span class="token number">2</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;completed&quot;</span><span class="token operator">:</span> <span class="token boolean">false</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>В Go JSON обрабатывает стандартный пакет <code>encoding/json</code>.</p><h2 id="сериализация-и-десериализация" tabindex="-1"><a class="header-anchor" href="#сериализация-и-десериализация"><span>Сериализация и десериализация</span></a></h2><p><strong>Сериализация</strong> превращает значение Go в последовательность байтов JSON:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">data<span class="token punctuation">,</span> err <span class="token operator">:=</span> json<span class="token punctuation">.</span><span class="token function">Marshal</span><span class="token punctuation">(</span>task<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>Десериализация</strong> восстанавливает значение Go из JSON-байтов:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">var</span> task Task</span>
<span class="line">err <span class="token operator">:=</span> json<span class="token punctuation">.</span><span class="token function">Unmarshal</span><span class="token punctuation">(</span>data<span class="token punctuation">,</span> <span class="token operator">&amp;</span>task<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><code>json.Marshal</code> возвращает <code>[]byte</code>, потому что JSON — текстовые данные в байтовом виде. Для вывода в терминал преобразуйте результат в строку:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token function">string</span><span class="token punctuation">(</span>data<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="сериализация-структуры" tabindex="-1"><a class="header-anchor" href="#сериализация-структуры"><span>Сериализация структуры</span></a></h2><p>Для начала возьмём знакомую структуру:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">type</span> Task <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">	ID        <span class="token builtin">int</span></span>
<span class="line">	Title     <span class="token builtin">string</span></span>
<span class="line">	Priority  <span class="token builtin">int</span></span>
<span class="line">	Completed <span class="token builtin">bool</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Поля с заглавной буквы экспортируются, поэтому <code>encoding/json</code> может прочитать и записать их:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">package</span> main</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">(</span></span>
<span class="line">	<span class="token string">&quot;encoding/json&quot;</span></span>
<span class="line">	<span class="token string">&quot;fmt&quot;</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> Task <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">	ID        <span class="token builtin">int</span></span>
<span class="line">	Title     <span class="token builtin">string</span></span>
<span class="line">	Priority  <span class="token builtin">int</span></span>
<span class="line">	Completed <span class="token builtin">bool</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	task <span class="token operator">:=</span> Task<span class="token punctuation">{</span>ID<span class="token punctuation">:</span> <span class="token number">1</span><span class="token punctuation">,</span> Title<span class="token punctuation">:</span> <span class="token string">&quot;Купить молоко&quot;</span><span class="token punctuation">,</span> Priority<span class="token punctuation">:</span> <span class="token number">2</span><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	data<span class="token punctuation">,</span> err <span class="token operator">:=</span> json<span class="token punctuation">.</span><span class="token function">Marshal</span><span class="token punctuation">(</span>task<span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token string">&quot;Не удалось сериализовать задачу:&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">		<span class="token keyword">return</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token function">string</span><span class="token punctuation">(</span>data<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Вывод будет похож на:</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span><span class="token property">&quot;ID&quot;</span><span class="token operator">:</span><span class="token number">1</span><span class="token punctuation">,</span><span class="token property">&quot;Title&quot;</span><span class="token operator">:</span><span class="token string">&quot;Купить молоко&quot;</span><span class="token punctuation">,</span><span class="token property">&quot;Priority&quot;</span><span class="token operator">:</span><span class="token number">2</span><span class="token punctuation">,</span><span class="token property">&quot;Completed&quot;</span><span class="token operator">:</span><span class="token boolean">false</span><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Имена ключей сейчас совпадают с именами Go-полей. Обычно для API и файлов используют нижний регистр, поэтому добавляют JSON-теги.</p><h2 id="json-теги" tabindex="-1"><a class="header-anchor" href="#json-теги"><span>JSON-теги</span></a></h2><p>Тег указывается после типа поля в обратных кавычках:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">type</span> Task <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">	ID        <span class="token builtin">int</span>    <span class="token string">\`json:&quot;id&quot;\`</span></span>
<span class="line">	Title     <span class="token builtin">string</span> <span class="token string">\`json:&quot;title&quot;\`</span></span>
<span class="line">	Priority  <span class="token builtin">int</span>    <span class="token string">\`json:&quot;priority&quot;\`</span></span>
<span class="line">	Completed <span class="token builtin">bool</span>   <span class="token string">\`json:&quot;completed&quot;\`</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Теперь JSON станет таким:</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span><span class="token property">&quot;id&quot;</span><span class="token operator">:</span><span class="token number">1</span><span class="token punctuation">,</span><span class="token property">&quot;title&quot;</span><span class="token operator">:</span><span class="token string">&quot;Купить молоко&quot;</span><span class="token punctuation">,</span><span class="token property">&quot;priority&quot;</span><span class="token operator">:</span><span class="token number">2</span><span class="token punctuation">,</span><span class="token property">&quot;completed&quot;</span><span class="token operator">:</span><span class="token boolean">false</span><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Тег меняет имя поля только во внешнем представлении JSON. В Go оно по-прежнему используется как <code>task.Title</code>.</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">task<span class="token punctuation">.</span>Title <span class="token operator">=</span> <span class="token string">&quot;Купить продукты&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">Поля должны быть экспортируемыми</p><p><code>encoding/json</code> игнорирует поля со строчной буквы. Например, поле <code>title string</code> не попадёт в JSON автоматически. Для модели, которую нужно сохранять или отдавать через API, используйте экспортируемые поля и JSON-теги.</p></div><h2 id="красивыи-json-json-marshalindent" tabindex="-1"><a class="header-anchor" href="#красивыи-json-json-marshalindent"><span>Красивый JSON: <code>json.MarshalIndent</code></span></a></h2><p><code>json.Marshal</code> создаёт компактный JSON в одну строку. Для файла, который читает человек, удобнее <code>json.MarshalIndent</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">data<span class="token punctuation">,</span> err <span class="token operator">:=</span> json<span class="token punctuation">.</span><span class="token function">MarshalIndent</span><span class="token punctuation">(</span>tasks<span class="token punctuation">,</span> <span class="token string">&quot;&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;  &quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Первый строковый аргумент — префикс каждой строки, второй — отступ одного уровня. Обычно используют пустой префикс и два пробела.</p><p>Пример результата:</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">[</span></span>
<span class="line">  <span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">&quot;id&quot;</span><span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;title&quot;</span><span class="token operator">:</span> <span class="token string">&quot;Купить молоко&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;priority&quot;</span><span class="token operator">:</span> <span class="token number">2</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;completed&quot;</span><span class="token operator">:</span> <span class="token boolean">false</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="десериализация-json-unmarshal" tabindex="-1"><a class="header-anchor" href="#десериализация-json-unmarshal"><span>Десериализация: <code>json.Unmarshal</code></span></a></h2><p><code>json.Unmarshal</code> получает JSON-байты и указатель на место, куда нужно записать результат:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">data <span class="token operator">:=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token function">byte</span><span class="token punctuation">(</span><span class="token string">\`{&quot;id&quot;:1,&quot;title&quot;:&quot;Купить молоко&quot;,&quot;priority&quot;:2,&quot;completed&quot;:false}\`</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">var</span> task Task</span>
<span class="line"><span class="token keyword">if</span> err <span class="token operator">:=</span> json<span class="token punctuation">.</span><span class="token function">Unmarshal</span><span class="token punctuation">(</span>data<span class="token punctuation">,</span> <span class="token operator">&amp;</span>task<span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">	fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token string">&quot;Некорректный JSON:&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">return</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span>task<span class="token punctuation">.</span>Title<span class="token punctuation">)</span> <span class="token comment">// Купить молоко</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Почему нужен <code>&amp;task</code>? <code>Unmarshal</code> должен изменить переменную <code>task</code>, а значит получает её адрес.</p><p>Для массива JSON создайте слайс:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">var</span> tasks <span class="token punctuation">[</span><span class="token punctuation">]</span>Task</span>
<span class="line"><span class="token keyword">if</span> err <span class="token operator">:=</span> json<span class="token punctuation">.</span><span class="token function">Unmarshal</span><span class="token punctuation">(</span>data<span class="token punctuation">,</span> <span class="token operator">&amp;</span>tasks<span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">return</span> err</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="что-делает-unmarshal-с-данными" tabindex="-1"><a class="header-anchor" href="#что-делает-unmarshal-с-данными"><span>Что делает Unmarshal с данными</span></a></h3><ul><li>отсутствующее в JSON поле остаётся с нулевым значением;</li><li>неизвестные поля JSON по умолчанию игнорируются;</li><li>несовместимый тип вызывает ошибку, например строка вместо числа для <code>priority</code>.</li></ul><p>JSON-декодирование проверяет формат, но не бизнес-правила. JSON с <code>&quot;priority&quot;: 10</code> корректен синтаксически, однако для нашей модели приоритет всё ещё недопустим. После загрузки задачи нужно валидировать теми же правилами, что и данные из другого источника.</p><h2 id="пустои-и-nil-слаис" tabindex="-1"><a class="header-anchor" href="#пустои-и-nil-слаис"><span>Пустой и nil-слайс</span></a></h2><p>Есть тонкое различие:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">var</span> nilTasks <span class="token punctuation">[</span><span class="token punctuation">]</span>Task</span>
<span class="line">emptyTasks <span class="token operator">:=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>Task<span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">nilJSON<span class="token punctuation">,</span> <span class="token boolean">_</span> <span class="token operator">:=</span> json<span class="token punctuation">.</span><span class="token function">Marshal</span><span class="token punctuation">(</span>nilTasks<span class="token punctuation">)</span></span>
<span class="line">emptyJSON<span class="token punctuation">,</span> <span class="token boolean">_</span> <span class="token operator">:=</span> json<span class="token punctuation">.</span><span class="token function">Marshal</span><span class="token punctuation">(</span>emptyTasks<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token function">string</span><span class="token punctuation">(</span>nilJSON<span class="token punctuation">)</span><span class="token punctuation">)</span>   <span class="token comment">// null</span></span>
<span class="line">fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token function">string</span><span class="token punctuation">(</span>emptyJSON<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token comment">// []</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Для списка задач в JSON обычно ожидают <code>[]</code>, а не <code>null</code>. Если экспортируете пустой список, создайте пустой слайс: <code>tasks := []task.Task{}</code>.</p><h2 id="сохранение-задач-в-json-фаил" tabindex="-1"><a class="header-anchor" href="#сохранение-задач-в-json-фаил"><span>Сохранение задач в JSON-файл</span></a></h2><p>Объединим JSON и файловый ввод-вывод. Сначала сериализуем слайс, затем записываем байты:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token function">SaveTasks</span><span class="token punctuation">(</span>path <span class="token builtin">string</span><span class="token punctuation">,</span> tasks <span class="token punctuation">[</span><span class="token punctuation">]</span>task<span class="token punctuation">.</span>Task<span class="token punctuation">)</span> <span class="token builtin">error</span> <span class="token punctuation">{</span></span>
<span class="line">	data<span class="token punctuation">,</span> err <span class="token operator">:=</span> json<span class="token punctuation">.</span><span class="token function">MarshalIndent</span><span class="token punctuation">(</span>tasks<span class="token punctuation">,</span> <span class="token string">&quot;&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;  &quot;</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;не удалось сериализовать задачи: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">:=</span> os<span class="token punctuation">.</span><span class="token function">WriteFile</span><span class="token punctuation">(</span>path<span class="token punctuation">,</span> data<span class="token punctuation">,</span> <span class="token number">0o644</span><span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;не удалось сохранить задачи: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">return</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Ошибки оборачиваются отдельно: так вызывающий код понимает, проблема возникла на этапе JSON или записи файла.</p><h2 id="загрузка-задач-из-json-фаила" tabindex="-1"><a class="header-anchor" href="#загрузка-задач-из-json-фаила"><span>Загрузка задач из JSON-файла</span></a></h2><p>Сначала прочитаем байты, затем десериализуем их в слайс:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token function">LoadTasks</span><span class="token punctuation">(</span>path <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span>task<span class="token punctuation">.</span>Task<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	data<span class="token punctuation">,</span> err <span class="token operator">:=</span> os<span class="token punctuation">.</span><span class="token function">ReadFile</span><span class="token punctuation">(</span>path<span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> <span class="token boolean">nil</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;не удалось прочитать задачи: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">var</span> tasks <span class="token punctuation">[</span><span class="token punctuation">]</span>task<span class="token punctuation">.</span>Task</span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">:=</span> json<span class="token punctuation">.</span><span class="token function">Unmarshal</span><span class="token punctuation">(</span>data<span class="token punctuation">,</span> <span class="token operator">&amp;</span>tasks<span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> <span class="token boolean">nil</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;не удалось разобрать JSON задач: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">return</span> tasks<span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Функция возвращает сразу два результата: список и ошибку. Если чтение или JSON-декодирование не удалось, список равен <code>nil</code>, а ошибка объясняет причину.</p><h2 id="пакет-internal-storage" tabindex="-1"><a class="header-anchor" href="#пакет-internal-storage"><span>Пакет <code>internal/storage</code></span></a></h2><p>Не держите JSON-хранилище в <code>main.go</code>. <code>main</code> должен собирать зависимости и запускать сценарий, а операции сохранения и загрузки — жить в отдельном пакете:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">task-manager/</span>
<span class="line">├── main.go</span>
<span class="line">└── internal/</span>
<span class="line">    ├── task/</span>
<span class="line">    │   └── task.go</span>
<span class="line">    └── storage/</span>
<span class="line">        ├── json.go</span>
<span class="line">        └── json_test.go</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>В <code>internal/storage/json.go</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">package</span> storage</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">(</span></span>
<span class="line">	<span class="token string">&quot;encoding/json&quot;</span></span>
<span class="line">	<span class="token string">&quot;fmt&quot;</span></span>
<span class="line">	<span class="token string">&quot;os&quot;</span></span>
<span class="line"></span>
<span class="line">	<span class="token string">&quot;example.com/task-manager/internal/task&quot;</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">SaveTasks</span><span class="token punctuation">(</span>path <span class="token builtin">string</span><span class="token punctuation">,</span> tasks <span class="token punctuation">[</span><span class="token punctuation">]</span>task<span class="token punctuation">.</span>Task<span class="token punctuation">)</span> <span class="token builtin">error</span> <span class="token punctuation">{</span></span>
<span class="line">	data<span class="token punctuation">,</span> err <span class="token operator">:=</span> json<span class="token punctuation">.</span><span class="token function">MarshalIndent</span><span class="token punctuation">(</span>tasks<span class="token punctuation">,</span> <span class="token string">&quot;&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;  &quot;</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;не удалось сериализовать задачи: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">:=</span> os<span class="token punctuation">.</span><span class="token function">WriteFile</span><span class="token punctuation">(</span>path<span class="token punctuation">,</span> data<span class="token punctuation">,</span> <span class="token number">0o644</span><span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;не удалось сохранить задачи: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">return</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">LoadTasks</span><span class="token punctuation">(</span>path <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span>task<span class="token punctuation">.</span>Task<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	data<span class="token punctuation">,</span> err <span class="token operator">:=</span> os<span class="token punctuation">.</span><span class="token function">ReadFile</span><span class="token punctuation">(</span>path<span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> <span class="token boolean">nil</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;не удалось прочитать задачи: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">var</span> tasks <span class="token punctuation">[</span><span class="token punctuation">]</span>task<span class="token punctuation">.</span>Task</span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">:=</span> json<span class="token punctuation">.</span><span class="token function">Unmarshal</span><span class="token punctuation">(</span>data<span class="token punctuation">,</span> <span class="token operator">&amp;</span>tasks<span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> <span class="token boolean">nil</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;не удалось разобрать JSON задач: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">return</span> tasks<span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>SaveTasks</code> и <code>LoadTasks</code> экспортируются, потому что их вызывает <code>main</code>. Детали JSON и файловой системы остаются внутри <code>storage</code>.</p><h2 id="тестирование-json-хранилища" tabindex="-1"><a class="header-anchor" href="#тестирование-json-хранилища"><span>Тестирование JSON-хранилища</span></a></h2><p>Файловое хранилище тестируют через <code>t.TempDir</code>, чтобы не создавать <code>tasks.json</code> в исходном проекте:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token function">TestSaveAndLoadTasks</span><span class="token punctuation">(</span>t <span class="token operator">*</span>testing<span class="token punctuation">.</span>T<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	path <span class="token operator">:=</span> filepath<span class="token punctuation">.</span><span class="token function">Join</span><span class="token punctuation">(</span>t<span class="token punctuation">.</span><span class="token function">TempDir</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token string">&quot;tasks.json&quot;</span><span class="token punctuation">)</span></span>
<span class="line">	wantTasks <span class="token operator">:=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>task<span class="token punctuation">.</span>Task<span class="token punctuation">{</span></span>
<span class="line">		<span class="token punctuation">{</span>ID<span class="token punctuation">:</span> <span class="token number">1</span><span class="token punctuation">,</span> Title<span class="token punctuation">:</span> <span class="token string">&quot;Купить молоко&quot;</span><span class="token punctuation">,</span> Priority<span class="token punctuation">:</span> <span class="token number">2</span><span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">:=</span> <span class="token function">SaveTasks</span><span class="token punctuation">(</span>path<span class="token punctuation">,</span> wantTasks<span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		t<span class="token punctuation">.</span><span class="token function">Fatalf</span><span class="token punctuation">(</span><span class="token string">&quot;SaveTasks вернул ошибку: %v&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	gotTasks<span class="token punctuation">,</span> err <span class="token operator">:=</span> <span class="token function">LoadTasks</span><span class="token punctuation">(</span>path<span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		t<span class="token punctuation">.</span><span class="token function">Fatalf</span><span class="token punctuation">(</span><span class="token string">&quot;LoadTasks вернул ошибку: %v&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">if</span> <span class="token operator">!</span>reflect<span class="token punctuation">.</span><span class="token function">DeepEqual</span><span class="token punctuation">(</span>gotTasks<span class="token punctuation">,</span> wantTasks<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">		t<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;LoadTasks = %#v, ожидалось %#v&quot;</span><span class="token punctuation">,</span> gotTasks<span class="token punctuation">,</span> wantTasks<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>В тесте используются <code>path/filepath</code>, <code>reflect</code>, <code>testing</code> и пакет <code>task</code>. <code>reflect.DeepEqual</code> подходит для сравнения слайсов структур в учебном примере. Позже можно выбрать более удобный инструмент сравнения, если модели станут сложнее.</p><p>Полезны и отдельные сценарии:</p><ul><li>сохранение пустого слайса как <code>[]</code>, а не <code>null</code>;</li><li>загрузка несуществующего файла с проверкой <code>errors.Is(err, os.ErrNotExist)</code>;</li><li>загрузка некорректного JSON;</li><li>проверка имён ключей <code>id</code>, <code>title</code>, <code>priority</code>, <code>completed</code> в записанном файле.</li></ul><h2 id="полныи-пример-task-manager-api" tabindex="-1"><a class="header-anchor" href="#полныи-пример-task-manager-api"><span>Полный пример Task Manager API</span></a></h2><p>Предположим, что тип <code>Task</code> с JSON-тегами расположен в <code>internal/task/task.go</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">package</span> task</span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> Task <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">	ID        <span class="token builtin">int</span>    <span class="token string">\`json:&quot;id&quot;\`</span></span>
<span class="line">	Title     <span class="token builtin">string</span> <span class="token string">\`json:&quot;title&quot;\`</span></span>
<span class="line">	Priority  <span class="token builtin">int</span>    <span class="token string">\`json:&quot;priority&quot;\`</span></span>
<span class="line">	Completed <span class="token builtin">bool</span>   <span class="token string">\`json:&quot;completed&quot;\`</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>В <code>main.go</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">package</span> main</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">(</span></span>
<span class="line">	<span class="token string">&quot;fmt&quot;</span></span>
<span class="line"></span>
<span class="line">	<span class="token string">&quot;example.com/task-manager/internal/storage&quot;</span></span>
<span class="line">	<span class="token string">&quot;example.com/task-manager/internal/task&quot;</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	tasks <span class="token operator">:=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>task<span class="token punctuation">.</span>Task<span class="token punctuation">{</span></span>
<span class="line">		<span class="token punctuation">{</span>ID<span class="token punctuation">:</span> <span class="token number">1</span><span class="token punctuation">,</span> Title<span class="token punctuation">:</span> <span class="token string">&quot;Купить молоко&quot;</span><span class="token punctuation">,</span> Priority<span class="token punctuation">:</span> <span class="token number">2</span><span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">		<span class="token punctuation">{</span>ID<span class="token punctuation">:</span> <span class="token number">2</span><span class="token punctuation">,</span> Title<span class="token punctuation">:</span> <span class="token string">&quot;Оплатить интернет&quot;</span><span class="token punctuation">,</span> Priority<span class="token punctuation">:</span> <span class="token number">3</span><span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">const</span> storagePath <span class="token operator">=</span> <span class="token string">&quot;tasks.json&quot;</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">:=</span> storage<span class="token punctuation">.</span><span class="token function">SaveTasks</span><span class="token punctuation">(</span>storagePath<span class="token punctuation">,</span> tasks<span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token string">&quot;Ошибка сохранения:&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">		<span class="token keyword">return</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	loadedTasks<span class="token punctuation">,</span> err <span class="token operator">:=</span> storage<span class="token punctuation">.</span><span class="token function">LoadTasks</span><span class="token punctuation">(</span>storagePath<span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token string">&quot;Ошибка загрузки:&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">		<span class="token keyword">return</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">for</span> <span class="token boolean">_</span><span class="token punctuation">,</span> currentTask <span class="token operator">:=</span> <span class="token keyword">range</span> loadedTasks <span class="token punctuation">{</span></span>
<span class="line">		fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span>currentTask<span class="token punctuation">.</span><span class="token function">Summary</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="частые-ошибки" tabindex="-1"><a class="header-anchor" href="#частые-ошибки"><span>Частые ошибки</span></a></h2><h3 id="передать-значение-вместо-адреса-в-unmarshal" tabindex="-1"><a class="header-anchor" href="#передать-значение-вместо-адреса-в-unmarshal"><span>Передать значение вместо адреса в Unmarshal</span></a></h3><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">var</span> tasks <span class="token punctuation">[</span><span class="token punctuation">]</span>Task</span>
<span class="line"><span class="token comment">// json.Unmarshal(data, tasks) // ошибка: нужен указатель</span></span>
<span class="line">json<span class="token punctuation">.</span><span class="token function">Unmarshal</span><span class="token punctuation">(</span>data<span class="token punctuation">,</span> <span class="token operator">&amp;</span>tasks<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>Unmarshal</code> должен записать загруженные данные в переменную.</p><h3 id="игнорирование-ошибки-json" tabindex="-1"><a class="header-anchor" href="#игнорирование-ошибки-json"><span>Игнорирование ошибки JSON</span></a></h3><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">data<span class="token punctuation">,</span> <span class="token boolean">_</span> <span class="token operator">:=</span> json<span class="token punctuation">.</span><span class="token function">Marshal</span><span class="token punctuation">(</span>tasks<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Не игнорируйте ошибку. Текущая структура может сериализоваться без проблем, но позже в неё могут появиться поля, которые JSON не поддерживает.</p><h3 id="ожидание-валидации-от-unmarshal" tabindex="-1"><a class="header-anchor" href="#ожидание-валидации-от-unmarshal"><span>Ожидание валидации от Unmarshal</span></a></h3><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span><span class="token property">&quot;id&quot;</span><span class="token operator">:</span><span class="token number">1</span><span class="token punctuation">,</span><span class="token property">&quot;title&quot;</span><span class="token operator">:</span><span class="token string">&quot;&quot;</span><span class="token punctuation">,</span><span class="token property">&quot;priority&quot;</span><span class="token operator">:</span><span class="token number">10</span><span class="token punctuation">,</span><span class="token property">&quot;completed&quot;</span><span class="token operator">:</span><span class="token boolean">false</span><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Это корректный JSON, но некорректная задача. После загрузки применяйте <code>IsValid()</code> или другую бизнес-валидацию.</p><h3 id="запись-nil-слаиса-когда-нужен" tabindex="-1"><a class="header-anchor" href="#запись-nil-слаиса-когда-нужен"><span>Запись <code>nil</code>-слайса, когда нужен <code>[]</code></span></a></h3><p><code>json.Marshal(nilTasks)</code> даст <code>null</code>. Для пустого списка создайте <code>[]task.Task{}</code>.</p><h3 id="тест-с-настоящим-tasks-json" tabindex="-1"><a class="header-anchor" href="#тест-с-настоящим-tasks-json"><span>Тест с настоящим <code>tasks.json</code></span></a></h3><p>Не запускайте тест с путём <code>&quot;tasks.json&quot;</code> из рабочей папки: он может зависеть от старого файла или перезаписать реальные данные. В тестах используйте <code>filepath.Join(t.TempDir(), &quot;tasks.json&quot;)</code>.</p><h2 id="дальше" tabindex="-1"><a class="header-anchor" href="#дальше"><span>Дальше</span></a></h2><p>Закрепите пакет JSON-хранилища и его тесты. После этого перейдём к времени и дедлайнам задач.</p>`,91)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};